import numpy as np

def problem(x: np.ndarray) -> float:
    x1, x2 = x
    return 0.1 * (x1**2 + x2**2) + 1.0 * x1 * x2 + 3.0 * np.exp(0.5 * (x1 + x2)) + 2.0 * np.cos(x1 + x2)

import numpy as np

def problem(x: np.ndarray) -> float:
    x = np.asarray(x)
    if x.shape != (2,):
        raise ValueError(f"Expected input of shape (2,), got {x.shape}")

    f = 0.1 * x[0]**2 + 0.2 * x[1]**2 + 0.3 * x[0] * x[1] + 0.1 * x[0] + 0.2 * x[1]
    f = abs(f)**0.7
    f = 0.003 * f + 0.001
    f += 0.2

    return float(f)

import numpy as np

def problem(x: np.ndarray) -> float:
    x1, x2 = x
    return 0.1 * (x1**2 + x2**2) + x1 * x2 + 3 * np.exp(0.5 * x1) + np.cos(x1+x2)

import numpy as np

def problem(x: np.ndarray) -> float:
    x1, x2 = x
    return 0.1 * (x1**2 + x2**2) + 1.0 * x1 * x2 + 3.0 * np.exp(0.5 * x1) + 2.0 * x2 * np.cos(x1 + x2) + np.sin(2*x1)

import numpy as np

def problem(x: np.ndarray) -> float:
    x1 = x[0]
    x2 = x[1]
    return (0.5 * x1**2 + 0.3 * x2**2 + 0.2 * x1 * x2) * np.exp(0.8 * x1) + 0.1 * x1 + 0.05 * x2 + 0.01 * np.exp(-(x1 + x2)**2)

import numpy as np

def problem(x: np.ndarray) -> float:
    x1 = x[0]
    x2 = x[1]
    return (0.5 * x1**2 + 0.3 * x2**2 + 0.2 * x1 * x2) * np.exp(0.8 * x1) + 0.1 * x1 + 0.05 * x2 + 0.01 * np.log(np.abs(x1 * x2) + 1)

import numpy as np

def problem(x: np.ndarray) -> float:
    x1 = x[0]
    x2 = x[1]
    return ((0.5 * x1**2 + 0.3 * x2**2 + 0.2 * x1 * x2) * np.exp(0.8 * x1) + 0.1 * x1 + 0.05 * x2) * (1 + 0.01 * (x1**3 + x2**3))

import numpy as np

def problem(x: np.ndarray) -> float:
    x1 = x[0]
    x2 = x[1]
    return 0.4 * (x1**2 + x2**2) * np.exp(0.6 * x1) + 0.1 * np.tanh(2 * x2)
